from collections import Counter

def min_extra_tiles(tiles):
    # Count the occurrences of each tile
    count = Counter(tiles)

    # Check for koutsu
    koutsu_needed = 0
    for tile, freq in count.items():
        if freq < 3:
            koutsu_needed += 3 - freq

    # Check for shuntsu
    suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
    shuntsu_needed = 0
    for suit in 'mps':
        tiles_in_suit = [tile for tile in tiles if tile.endswith(suit)]
        tiles_in_suit.sort()
        i = 0
        while i < len(tiles_in_suit):
            if i + 2 < len(tiles_in_suit) and int(tiles_in_suit[i+1][:-1]) == int(tiles_in_suit[i][:-1]) + 1 and int(tiles_in_suit[i+2][:-1]) == int(tiles_in_suit[i][:-1]) + 2:
                i += 3
            else:
                shuntsu_needed += 1
                i += 1

    # Return the maximum of koutsu_needed and shuntsu_needed
    return max(koutsu_needed, shuntsu_needed)

